	private double sliceRows = -1D;
	private boolean distinctConsumer;
	private String forcedTag;
	private RowState sharedRow;
	private RowState.AttemptStart sharedRowStart;
	private LmdbNativeStaticPrior prior = LmdbNativeStaticPrior.DEFAULT;

	LmdbNativeDispatchLoop(LmdbNativeDecisionPoint point, List<? extends LmdbNativeStrategy<C, T>> strategies,
			TupleExpr explainTarget) {
		this.point = point;
		this.strategies = List.copyOf(strategies);
		this.explainTarget = explainTarget;
		this.label = point.label();
		for (LmdbNativeStrategy<C, T> strategy : this.strategies) {
			if (strategy.point() != point) {
				throw new IllegalArgumentException(strategy.id() + " belongs to " + strategy.point() + ", not "
						+ point);
			}
		}
	}

	/** A finite consumer row limit; streaming work is prorated by the share of the result it asks for. */
	LmdbNativeDispatchLoop<C, T> slice(double rows) {
		return slice(rows, false);
	}

	/** A distinct consumer counts output keys; only certified distinct candidates share its raw-row budget. */
	LmdbNativeDispatchLoop<C, T> slice(double rows, boolean distinctConsumer) {
		this.sliceRows = rows;
		this.distinctConsumer = distinctConsumer;
		return this;
	}

	private LmdbNativeCostVector consumedQuote(LmdbNativeCandidate<?> candidate) {
		LmdbNativeCostQuote quote = candidate.quote();
		return quote.forSlice(LmdbNativeSelector.consumableRows(quote, sliceRows, distinctConsumer));
	}

